style.css:
@-moz-document domain("youtube.com") {
/* ---- GLOBAL BG ---- */
  body, ytd-app, #content, #page-manager {
    background: #e8f3ff !important; /* bright, soft blue */
    color: #0a2a50 !important;
  }

  /* ---- TOP BAR ---- */
  ytd-masthead {
    background: #1e90ff !important; /* main bright blue */
    border-bottom: none !important;
    color: white !important;
  }

  /* ---- SEARCH BAR ---- */
  #search-input input {
    background: white !important;
    border: 2px solid #1e90ff !important;
    border-radius: 8px !important;
    color: #0a2a50 !important;
  }

  #search-icon-legacy {
    background: #1e90ff !important;
    border-radius: 8px !important;
  }

  /* ---- VIDEO CARDS ---- */
  ytd-rich-item-renderer,
  ytd-video-renderer {
    background: white !important;
    border-radius: 12px !important;
    border: 2px solid #bcdcff !important;
    box-shadow: none !important;
  }

  /* ---- TITLES ---- */
  #video-title {
    color: #06457a !important;
    font-weight: 600 !important;
  }

  /* ---- LINKS ---- */
  a, yt-formatted-string {
    color: #0759a8 !important;
  }

  /* ---- BUTTONS ---- */
  ytd-subscribe-button-renderer button {
    background: #1e90ff !important;
    color: white !important;
    border-radius: 20px !important;
    border: none !important;
  }

  /* ---- COMMENTS ---- */
  #comments {
    background: white !important;
    border-radius: 12px !important;
    border: 2px solid #bcdcff !important;
  }

  #content-text {
    color: #0a2a50 !important;
  }

  /* ---- SCROLLBAR ---- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: #1e90ff !important;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #e8f3ff !important;
  }
}
